        starter: G.twoStart, solution: G.two,
        goals: [goal(L('Two adapters with attention masks', 'Dos adaptadors amb màscares d’atenció', 'Dos adaptadores con máscaras de atención'), (g, c) => ran(c, h => h.maskedAdapters >= 2)), goal(L('Anna on the left, Leo on the right', 'L’Anna a l’esquerra, el Leo a la dreta', 'Anna a la izquierda, Leo a la derecha'), (g, c) => ran(c, h => h.persons.some(p => p.x < .5 && p.ref === 'portrait_anna.png' && p.score >= .7) && h.persons.some(p => p.x > .5 && p.ref === 'portrait_leo.png' && p.score >= .7)))],
